"""Export a fully self-contained, offline browser dashboard for easy review."""
from pathlib import Path
import json, joblib, numpy as np, pandas as pd
ROOT=Path(__file__).resolve().parents[1]
data=pd.read_csv(ROOT/'data/processed/event_study.csv')
upcoming=pd.read_csv(ROOT/'data/processed/upcoming_events.csv')
research=pd.read_csv(ROOT/'data/processed/research_links.csv').fillna('')
metrics=pd.read_csv(ROOT/'outputs/metrics.csv')
status_path=ROOT/'outputs/live_status.json'
live_status=json.loads(status_path.read_text()) if status_path.exists() else {}
bundle=joblib.load(ROOT/'outputs/models.joblib')
pre_bundle=joblib.load(ROOT/'outputs/pre_release_models.joblib')
pre_metrics=pd.read_csv(ROOT/'outputs/pre_release_models.gold_metrics.csv')
models={}
for h,pair in bundle['models'].items():
    entry={}
    for kind in ['direction','return']:
        pipe=pair[kind]; pre=pipe.named_steps['features']
        imp=pre.named_transformers_['num'].named_steps['impute']
        scale=pre.named_transformers_['num'].named_steps['scale']
        cats=pre.named_transformers_['cat'].categories_[0].tolist()
        coef=pipe.named_steps['model'].coef_
        entry[kind]={'median':imp.statistics_.tolist(),'mean':scale.mean_.tolist(),'scale':scale.scale_.tolist(),
                     'cats':cats,'coef':np.asarray(coef).reshape(-1).tolist(),
                     'intercept':float(np.asarray(pipe.named_steps['model'].intercept_).reshape(-1)[0])}
    entry['calibration']=pair.get('calibration',{'a':1.0,'b':0.0})
    models[h]=entry
pipe=pre_bundle['final_model'];pre=pipe.named_steps['features']
imp=pre.named_transformers_['num'].named_steps['impute'];scale=pre.named_transformers_['num'].named_steps['scale']
pre_model={'median':imp.statistics_.tolist(),'mean':scale.mean_.tolist(),'scale':scale.scale_.tolist(),
           'cats':pre.named_transformers_['cat'].categories_[0].tolist(),
           'coef':pipe.named_steps['model'].coef_.reshape(-1).tolist(),'intercept':float(pipe.named_steps['model'].intercept_)}
pre_residuals={k:np.asarray(v).tolist() for k,v in pre_bundle['surprise_residuals'].items()}
reaction_residuals={h:{e:float(s) for e,s in vals.items()} for h,vals in pre_bundle['reaction_residuals'].items()}
cols=['release_time','event_type','actual','forecast','previous','surprise_sigma','surprise_z','signed_surprise_z','gold_surprise_sign','return_5m','return_15m','return_1h','return_4h','return_24h','mfe_1h','mae_1h']
events=json.loads(data[cols].to_json(orient='records'))
payload={'events':events,'upcoming':json.loads(upcoming.to_json(orient='records')),
         'research':json.loads(research.to_json(orient='records')),'metrics':json.loads(metrics.to_json(orient='records')),
         'preMetrics':json.loads(pre_metrics.to_json(orient='records')),'preModel':pre_model,
         'preResiduals':pre_residuals,'reactionResiduals':reaction_residuals,'marketContext':{**(json.loads((ROOT/'outputs/market_context.json').read_text()) if (ROOT/'outputs/market_context.json').exists() else {}), **{k:v for k,v in live_status.items() if k in ('pre_return_24h','last_bid','price_timestamp')}},
         'liveQuotes':json.loads((ROOT/'outputs/live_quotes.json').read_text()) if (ROOT/'outputs/live_quotes.json').exists() else {},
         'researchIntelligence':json.loads((ROOT/'outputs/research_intelligence.json').read_text()) if (ROOT/'outputs/research_intelligence.json').exists() else {},
         'liveScoring':(pd.read_csv(ROOT/'outputs/live_scoring.csv').to_dict('records') if (ROOT/'outputs/live_scoring.csv').exists() else []),
         'calibration':(pd.read_csv(ROOT/'outputs/calibration.csv').to_dict('records') if (ROOT/'outputs/calibration.csv').exists() else []),
         'platt':{h:{'a':v['calibration']['a'],'b':v['calibration']['b']} for h,v in models.items() if 'calibration' in v},
         'frozenForecasts':{r['event_type']:r for r in (pd.read_csv(ROOT/'outputs/forecast_log.csv').sort_values('forecast_time').groupby('event_type').tail(1).to_dict('records') if (ROOT/'outputs/forecast_log.csv').exists() else [])},
         'forecastLog':json.loads(pd.read_csv(ROOT/'outputs/forecast_log.csv').tail(200).to_json(orient='records')) if (ROOT/'outputs/forecast_log.csv').exists() else [],'models':models}
html=r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gold News Lab</title><style>
:root{--ink:#18222d;--gold:#b88725;--muted:#657383;--line:#e3e5e8;--soft:#f6f4ef}*{box-sizing:border-box}body{font:15px/1.5 system-ui,-apple-system,sans-serif;color:var(--ink);margin:0;background:#fafbfc}header{padding:28px max(22px,calc((100% - 1180px)/2));background:#102a43;color:white}header h1{margin:0 0 4px;font-size:28px}header p{margin:0;color:#d8e3ee}main{max-width:1180px;margin:auto;padding:20px}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:22px}.tabs button{border:1px solid var(--line);background:white;padding:10px 14px;border-radius:8px;cursor:pointer}.tabs button.active{background:#102a43;color:white}.panel{display:none}.panel.active{display:block}h2{margin-top:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.card{background:white;border:1px solid var(--line);border-radius:10px;padding:16px}.metric{font-size:23px;font-weight:700}.muted{color:var(--muted);font-size:13px}label{display:block;font-weight:600;margin:12px 0 4px}input,select{width:100%;padding:10px;border:1px solid #bcc5cf;border-radius:7px;background:white;font:inherit}table{border-collapse:collapse;width:100%;background:white;font-size:13px;margin:12px 0 24px;display:block;overflow-x:auto}th,td{padding:9px 10px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{background:var(--soft)}.note{background:#fff7dc;border-left:4px solid #d69e2e;padding:13px;margin:12px 0}.good{background:#eaf7f1;border-left:4px solid #16866b;padding:13px;margin:12px 0}a{color:#1769aa}.pill{padding:3px 8px;border-radius:12px;background:#eee}.footer{color:var(--muted);font-size:12px;margin:25px 0}.article{padding:11px 0;border-bottom:1px solid var(--line)}@media(max-width:600px){main{padding:12px}header{padding:22px}.card{padding:12px}}
</style></head><body><header><h1>🟡 Gold News Lab</h1><p>US macroeconomic releases → XAUUSD · offline review dashboard</p><p style="margin-top:8px;font-size:13px"><b>Data refreshed:</b> __GENERATED__ &nbsp;·&nbsp; <b>Latest XAUUSD bid timestamp:</b> __PRICE_TIME__</p></header><main><div class="tabs"><button data-tab="upcoming" class="active">Upcoming event</button><button data-tab="scenario">Scenario analyzer</button><button data-tab="history">Historical reactions</button><button data-tab="validation">Validation</button></div>
<section id="upcoming" class="panel active"><h2>Pre-event analyst workspace</h2><div class="note">Conditional scenarios—not predictions of the unpublished actual. Research headlines are discovery links, not verified model facts.</div><label>Scheduled release</label><select id="upEvent"></select><div id="upMeta" class="grid"></div><div class="grid"><div><label>Working consensus</label><input id="upForecast" type="number" step="any"></div><div><label>Current XAUUSD prior-24h return (%)</label><input id="upTrend" type="number" step="0.1"></div></div><h3>Pre-release forecast</h3><div class="grid"><div><label>Forecast horizon</label><select id="preHorizon"><option>1h</option><option>4h</option><option>24h</option></select></div><div><label>Analyst data-outcome tilt (σ)</label><input id="researchTilt" type="number" value="0" min="-1" max="1" step="0.1"></div></div><div id="forecastOut"></div><h3>Scenario stress test</h3><div id="scenarioOut"></div><h3>Recent research and commentary</h3><div id="researchOut"></div><div class="good"><b>Analyst checklist:</b> verify consensus and revisions; check DXY, real yields and Fed pricing; consider positioning and simultaneous releases. For jobs, read payrolls, wages, unemployment and revisions together.</div></section>
<section id="scenario" class="panel"><h2>Post-release scenario analyzer</h2><div class="note">Enter actual and consensus after publication. Probabilities near 50% mean low conviction; expected returns are model means, not targets.</div><div class="grid"><div><label>Release</label><select id="scEvent"></select></div><div><label>Actual</label><input id="scActual" type="number" step="any"></div><div><label>Consensus</label><input id="scForecast" type="number" step="any"></div><div><label>Prior-24h XAUUSD return (%)</label><input id="scTrend" type="number" value="0" step="0.1"></div></div><label>Final post-release forecast horizon</label><select id="postHorizon"><option>1h</option><option>4h</option><option>24h</option></select><div id="finalPost"></div><div id="scOut"></div><h3>Closest broad historical analogs</h3><div id="analogs"></div></section>
<section id="history" class="panel"><h2>Historical event explorer</h2><div class="grid"><div><label>Event</label><select id="histEvent"></select></div><div><label>Horizon</label><select id="histHorizon"><option>5m</option><option>15m</option><option selected>1h</option><option>4h</option><option>24h</option></select></div><div><label>Surprise regime</label><select id="histRegime"><option>All</option><option>Gold-bullish</option><option>In line</option><option>Gold-bearish</option></select></div></div><div id="histStats" class="grid" style="margin-top:14px"></div><div id="histOut"></div></section>
<section id="validation" class="panel"><h2>Out-of-time validation (2025 onward)</h2><div class="note">Small test sample. Accuracy near 50% and AUC near 0.5 indicate no demonstrated direction edge. Trade columns are diagnostics, not a portfolio backtest.</div><h3>Pre-release forecast model</h3><div id="preMetricsOut"></div><h3>Post-release reaction model</h3><div id="metricsOut"></div><p><b>Consensus source:</b> Forex Factory history (independent), matched to TradingView release timestamps; TradingView is the fallback, and 16 FOMC meetings still use a no-change proxy. Two sources agree exactly on about 80% of overlapping events.</p><p><b>Method:</b> regularized logistic regression for direction and ridge regression for return magnitude. Training uses pre-2025 data; testing uses 2025 onward.</p><h3>What a probability actually means (out-of-fold calibration)</h3><div class="note">Read this before trusting any percentage. If a model says 88% and the event happened 75% of the time, the model is overconfident.</div><div id="calibOut"></div><h3>Live scored accuracy (forward test, not backtest)</h3><div class="note">Filled automatically once each release and its horizon have elapsed. This is the only evidence that is not in-sample.</div><div id="liveScoreOut"></div><h3>Timestamped forecast log</h3><div id="forecastLogOut"></div></section><div class="footer">Sources: Dukascopy public XAUUSD feed; TradingView US economic calendar. Research use only—not financial advice. This standalone copy contains a snapshot of the data and models.</div></main><script>
const DB=__DATABASE__;
const $=id=>document.getElementById(id), types=[...new Set(DB.events.map(x=>x.event_type))].sort();
const signs=Object.fromEntries(types.map(t=>[t,DB.events.find(x=>x.event_type===t).gold_surprise_sign]));
const fmt=(x,n=2)=>x==null||!isFinite(x)?'—':Number(x).toFixed(n), pct=x=>x==null?'—':(x*100).toFixed(2)+'%';
function table(rows,cols){if(!rows.length)return '<p>No records.</p>';return '<table><thead><tr>'+cols.map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+cols.map(c=>'<td>'+(r[c]??'—')+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}
function sigma(t){return DB.events.filter(x=>x.event_type===t).at(-1).surprise_sigma||1}
function predict(t,signedZ,trend,hour=13.5){let out=[];for(const h of ['1h','4h','24h']){let raw=[signedZ,Math.abs(signedZ),trend,null,Math.sin(2*Math.PI*hour/24),Math.cos(2*Math.PI*hour/24),DB.marketContext.dxy_return_24h??null,DB.marketContext.oil_return_24h??null,DB.marketContext.volatility_change_24h??null,DB.marketContext.dgs2_change_5d??null,DB.marketContext.dgs10_change_5d??null,DB.marketContext.real_yield_change_5d??null];let row={Horizon:h};for(const kind of ['direction','return']){let m=DB.models[h][kind],v=raw.map((x,i)=>x==null?m.median[i]:x).map((x,i)=>(x-m.mean[i])/m.scale[i]);v=v.concat(m.cats.map(c=>c===t?1:0));let score=m.intercept+m.coef.reduce((s,c,i)=>s+c*v[i],0);if(kind==='direction')row['P(up)']=fmt(100/(1+Math.exp(-score)),1)+'%';else row['Expected bps']=fmt(score*10000,1)}out.push(row)}return out}
function preForecast(u,f,prev,trend,h,tilt){let hist=DB.events.filter(x=>x.event_type===u.event_type),last=hist.at(-1),s=sigma(u.event_type),m=DB.preModel;let raw=[(f-prev)/s,last.surprise_z,hist.slice(-2).reduce((a,x)=>a+x.surprise_z,0)/2,trend,null];let v=raw.map((x,i)=>x==null?m.median[i]:x).map((x,i)=>(x-m.mean[i])/m.scale[i]);v=v.concat(m.cats.map(c=>c===u.event_type?1:0));let mu=m.intercept+m.coef.reduce((a,c,i)=>a+c*v[i],0)+tilt,res=DB.preResiduals[u.event_type]||DB.preResiduals.ALL;res=res.slice().sort((a,b)=>a-b);let zs=res.map(r=>mu+r),means=[],ps=[];for(const z of zs){let hour=+u.release_time.slice(11,13)+u.release_time.slice(14,16)/60;let p=predict(u.event_type,signs[u.event_type]*z,trend,hour).find(x=>x.Horizon===h);means.push(parseFloat(p['Expected bps'])/10000);ps.push(platt(parseFloat(p['P(up)'])/100,h))}let pUp=ps.reduce((a,x)=>a+x,0)/ps.length,mean=means.reduce((a,x)=>a+x,0)/means.length,varZ=means.reduce((a,x)=>a+(x-mean)**2,0)/means.length,rs=DB.reactionResiduals[h][u.event_type]||DB.reactionResiduals[h].ALL,sd=Math.sqrt(varZ+rs*rs),label=pUp>=.5?'WHAT-IF: BULLISH':'WHAT-IF: BEARISH',prob=Math.max(pUp,1-pUp),research=(DB.researchIntelligence[u.event_type]||{}).signal||'Mixed/neutral',conflict=(label.endsWith('BULLISH')&&research==='Bearish context')||(label.endsWith('BEARISH')&&research==='Bullish context'),confidence=prob>=.60&&!conflict?'Moderate':'Low';return `<div class="good" style="font-size:22px"><b>${label} · ${fmt(prob*100,1)}%</b><div style="font-size:14px;margin-top:6px">Confidence: ${confidence}. Combines surprise distribution, historical reactions, DXY/oil/yields, gold trend and analyst tilt. Headline context: <b>${research}</b> (unvalidated, not auto-applied). ${conflict?'It conflicts with the numerical forecast, reducing confidence.':''}</div></div><div class="note"><b>Live gold cross-check:</b> ${livePanel()}</div><div class="note"><b>Market context:</b> DXY 24h ${pct(DB.marketContext.dxy_return_24h)} · Brent 24h ${pct(DB.marketContext.oil_return_24h)} · US 2Y 5d ${fmt(DB.marketContext.dgs2_change_5d)} pp · US 10Y 5d ${fmt(DB.marketContext.dgs10_change_5d)} pp · Real 10Y 5d ${fmt(DB.marketContext.real_yield_change_5d)} pp</div><div class="grid"><div class="card"><div class="muted">P(gold up)</div><div class="metric">${fmt(pUp*100,1)}%</div></div><div class="card"><div class="muted">P(gold down)</div><div class="metric">${fmt((1-pUp)*100,1)}%</div></div><div class="card"><div class="muted">Expected move</div><div class="metric">${fmt(mean*100,2)}%</div></div><div class="card"><div class="muted">80% model range</div><div class="metric">${fmt((mean-1.2816*sd)*100,2)}% to ${fmt((mean+1.2816*sd)*100,2)}%</div></div><div class="card"><div class="muted">Expected actual</div><div class="metric">${fmt(f+mu*s,4)}</div></div><div class="card"><div class="muted">P(actual beats consensus)</div><div class="metric">${fmt(zs.filter(z=>z>0).length/zs.length*100,1)}%</div></div></div><p class="muted">This block recomputes in your browser from the sliders, so it can differ from the pipeline call at the top. Pre-release surprise distribution integrated with historical reaction models. Research tilt is an explicit assumption, not an automated article score. Out-of-time performance is weak; this is decision support, not a trade command.</p>`}
function platt(p,h){let c=(DB.platt||{})[h];if(!c||!isFinite(p)||p<=0||p>=1)return p;let l=Math.log(p/(1-p));return 1/(1+Math.exp(-(c.a*l+c.b)))}
function livePanel(){let q=DB.liveQuotes||{},v=q.venues||{},parts=[];for(const k of Object.keys(v))parts.push(v[k].price?`${k} ${fmt(v[k].price,2)}`:`${k} n/a`);
let age=q.fetched_at?(Date.now()-new Date(q.fetched_at))/60000:null;
return `${parts.join(' · ')}${q.median?` · median ${fmt(q.median,2)}`:''}${q.spread_pct!=null?` · venue spread ${fmt(q.spread_pct,3)}%`:''}${age!=null?` · fetched ${fmt(age,0)} min ago`:''} <span class="muted">(tokenized gold proxy, not XAUUSD; used for freshness monitoring only)</span>`}
function init(){document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button,.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.tab).classList.add('active')});$('upEvent').innerHTML=DB.upcoming.map((x,i)=>`<option value="${i}">${x.event_type} — ${x.release_time.replace('T',' ').slice(0,16)} UTC</option>`).join('');for(const id of ['scEvent','histEvent'])$(id).innerHTML=types.map(t=>`<option>${t}</option>`).join('');$('upEvent').onchange=upInputs;$('upForecast').oninput=upRender;$('upTrend').oninput=upRender;$('preHorizon').onchange=upRender;$('researchTilt').oninput=upRender;$('scEvent').onchange=scInputs;for(const id of ['scActual','scForecast','scTrend'])$(id).oninput=scRender;$('postHorizon').onchange=scRender;for(const id of ['histEvent','histHorizon','histRegime'])$(id).onchange=histRender;upInputs();scInputs();histRender();metricsRender()}
function upInputs(){let u=DB.upcoming[$('upEvent').value];$('upTrend').value=DB.marketContext&&DB.marketContext.pre_return_24h!=null?fmt(DB.marketContext.pre_return_24h*100,2):0;$('upForecast').value=u.forecast??u.previous??DB.events.filter(x=>x.event_type===u.event_type).at(-1).actual;$('upMeta').innerHTML=`<div class="card"><div class="muted">Release</div><div class="metric">${u.event_type}</div></div><div class="card"><div class="muted">Previous</div><div class="metric">${u.previous??'—'}</div></div><div class="card"><div class="muted">Feed consensus</div><div class="metric">${u.forecast??'Not published'}</div></div>`;upRender()}
function frozenCard(u){let r=(DB.frozenForecasts||{})[u.event_type];if(!r)return '';let dir=String(r.direction).toUpperCase(),prob=dir==='BULLISH'?r.probability_up:1-r.probability_up,conf=prob>=.60?'Moderate':'Low';
let res=(r.return_1h!=null&&isFinite(r.return_1h))?`<div class="note"><b>Scored:</b> actual ${r.actual!=null?r.actual:'n/a'} · 1h ${pct(r.return_1h)} · 4h ${r.return_4h!=null?pct(r.return_4h):'pending'} · 24h ${r.return_24h!=null?pct(r.return_24h):'pending'} → <b>${(r.return_1h>0)===(dir==='BULLISH')?'CORRECT':'WRONG'}</b></div>`:'<div class="note">Outcome not scored yet — the release or its 1h window has not elapsed.</div>';
return `<div class="good" style="font-size:22px;margin-bottom:6px"><b>PIPELINE CALL (frozen): ${dir} · ${fmt(prob*100,1)}%</b><div style="font-size:14px;margin-top:6px">Recorded ${String(r.forecast_time).replace('T',' ').slice(0,16)} UTC for the ${u.release_time.slice(0,10)} release at the ${r.horizon} horizon · Confidence: ${conf} · Consensus ${r.consensus}</div><div style="font-size:14px;margin-top:4px">Expected move ${pct(r.expected_return)} · 80% range ${pct(r.lower_80)} to ${pct(r.upper_80)}</div></div>${res}<div class="note">This is the call the automated pipeline produced and logged. The block below is a <b>what-if</b> that recomputes from your slider inputs and will usually differ.</div>`}
function upRender(){let u=DB.upcoming[$('upEvent').value],f=+$('upForecast').value,s=sigma(u.event_type),hour=+u.release_time.slice(11,13)+u.release_time.slice(14,16)/60,rows=[];let prev=u.previous??DB.events.filter(x=>x.event_type===u.event_type).at(-1).previous;$('forecastOut').innerHTML=frozenCard(u)+'<h3>Interactive what-if (your inputs)</h3>'+preForecast(u,f,prev,+$('upTrend').value/100,$('preHorizon').value,+$('researchTilt').value||0);for(const [name,z] of [['Much stronger',1.5],['Stronger',.75],['In line',0],['Weaker',-.75],['Much weaker',-1.5]]){let ps=predict(u.event_type,signs[u.event_type]*z,+$('upTrend').value/100,hour),r={Scenario:name,'Hypothetical actual':fmt(f+z*s,4)};for(const h of ['1h','4h','24h']){r[h+' P(up)']=ps.find(x=>x.Horizon===h)['P(up)'];r[h+' bps']=ps.find(x=>x.Horizon===h)['Expected bps']}rows.push(r)}$('scenarioOut').innerHTML=table(rows,Object.keys(rows[0]));let arts=DB.research.filter(x=>x.event_type===u.event_type);$('researchOut').innerHTML=arts.length?arts.map(a=>`<div class="article"><span class="muted">${a.published_at} · ${a.source}</span><br><a href="${a.url}" target="_blank" rel="noopener">${a.title}</a></div>`).join(''):'<p>No research links collected.</p>'}
function scInputs(){let t=$('scEvent').value,last=DB.events.filter(x=>x.event_type===t).at(-1);$('scActual').value=last.actual;$('scForecast').value=last.forecast;scRender()}
function scRender(){let t=$('scEvent').value,z=(+$('scActual').value-+$('scForecast').value)/sigma(t),signed=signs[t]*z,rows=predict(t,signed,+$('scTrend').value/100),h=$('postHorizon').value,matches=DB.events.filter(x=>x.event_type===t&&Math.abs(x.signed_surprise_z-signed)<.75&&x['return_'+h]!=null),modelP=parseFloat(rows.find(x=>x.Horizon===h)['P(up)'])/100,analogP=matches.length?matches.filter(x=>x['return_'+h]>0).length/matches.length:.5,finalP=.5*modelP+.5*analogP,dir=finalP>=.5?'BULLISH':'BEARISH',macro=signed>.25?'BEARISH':signed<-.25?'BULLISH':'MIXED',modelDir=modelP>=.5?'BULLISH':'BEARISH',agree=macro===modelDir,prob=Math.max(finalP,1-finalP),confidence=agree&&prob>=.60?'Moderate':'Low';$('finalPost').innerHTML=`<div class="good" style="font-size:22px;margin-top:14px"><b>FINAL POST-RELEASE: ${dir} · ${fmt(prob*100,1)}%</b><div style="font-size:14px;margin-top:6px">Confidence: ${confidence}. Blends reaction model (${fmt(modelP*100,1)}% up) with ${matches.length} similar historical releases (${fmt(analogP*100,1)}% up). Macro: ${macro.toLowerCase()}; model: ${modelDir.toLowerCase()}. ${agree?'Signals agree.':'Signals conflict, so conviction is reduced.'}</div></div>`;$('scOut').innerHTML=`<h3>Standardized surprise: ${fmt(z)}σ · ${signed>.25?'Gold-bullish':signed<-.25?'Gold-bearish':'Approximately in line'}</h3>`+table(rows,['Horizon','P(up)','Expected bps']);let a=matches.slice(-10).reverse().map(x=>({Date:x.release_time.slice(0,10),Actual:x.actual,Forecast:x.forecast,'Surprise σ':fmt(x.surprise_z),'1h':pct(x.return_1h),'4h':pct(x.return_4h),'24h':pct(x.return_24h)}));$('analogs').innerHTML=table(a,['Date','Actual','Forecast','Surprise σ','1h','4h','24h'])}
function histRender(){let t=$('histEvent').value,h=$('histHorizon').value,r=$('histRegime').value,key='return_'+h,a=DB.events.filter(x=>x.event_type===t&&x[key]!=null);if(r==='Gold-bullish')a=a.filter(x=>x.signed_surprise_z>.25);if(r==='Gold-bearish')a=a.filter(x=>x.signed_surprise_z<-.25);if(r==='In line')a=a.filter(x=>Math.abs(x.signed_surprise_z)<=.25);let vals=a.map(x=>x[key]).sort((a,b)=>a-b),mean=vals.reduce((s,x)=>s+x,0)/(vals.length||1),mid=vals.length%2?vals[(vals.length-1)/2]:(vals[vals.length/2-1]+vals[vals.length/2])/2;$('histStats').innerHTML=[['Events',a.length],['Mean',fmt(mean*10000,1)+' bps'],['Median',fmt(mid*10000,1)+' bps'],['Up frequency',fmt(vals.filter(x=>x>0).length/(vals.length||1)*100,1)+'%']].map(x=>`<div class="card"><div class="muted">${x[0]}</div><div class="metric">${x[1]}</div></div>`).join('');let rows=a.slice().reverse().map(x=>({Date:x.release_time.slice(0,10),Actual:x.actual,Forecast:x.forecast,Previous:x.previous,'Surprise σ':fmt(x.surprise_z),Return:pct(x[key])}));$('histOut').innerHTML=table(rows,['Date','Actual','Forecast','Previous','Surprise σ','Return'])}
function metricsRender(){let rows=DB.metrics.map(x=>({Horizon:x.horizon,Events:x.test_events,Accuracy:fmt(x.direction_accuracy*100,1)+'%',AUC:fmt(x.roc_auc,3),'MAE bps':fmt(x.mae_bps,1),Trades:x.trades,'Hit rate':fmt(x.trade_hit_rate*100,1)+'%'}));$('metricsOut').innerHTML=table(rows,Object.keys(rows[0]));let pre=DB.preMetrics.map(x=>({Horizon:x.horizon,Events:x.test_events,Accuracy:fmt(x.direction_accuracy*100,1)+'%',Majority:fmt(x.majority_accuracy*100,1)+'%',AUC:fmt(x.roc_auc,3),'MAE bps':fmt(x.mae_bps,1)}));$('preMetricsOut').innerHTML=table(pre,Object.keys(pre[0]));let logs=DB.forecastLog.slice().reverse().map(x=>({Forecasted:x.forecast_time?.slice(0,16),Event:x.event_type,Release:String(x.release_time).slice(0,10),Call:x.direction,'P(up)':fmt(x.probability_up*100,1)+'%',Actual:x.actual,'1h outcome':pct(x.return_1h)}));let cb=(DB.calibration||[]).map(x=>({Horizon:x.horizon,'Model said':fmt(x.predicted,1)+'%','Actually went up':fmt(x.actual,1)+'%',Events:x.n,'Chance baseline':fmt(x.base_rate,1)+'%'}));let ls=(DB.liveScoring||[]).filter(x=>x.n_scored>0).map(x=>({Horizon:x.horizon,'Scored forecasts':x.n_scored,'Hit rate':fmt(x.hit_rate*100,1)+'%','Mean stated confidence':fmt(x.mean_stated_confidence*100,1)+'%',Brier:fmt(x.brier,3),'Brier (base rate)':fmt(x.brier_base_rate,3)}));$('liveScoreOut').innerHTML=ls.length?table(ls,['Horizon','Scored forecasts','Hit rate','Mean stated confidence','Brier','Brier (base rate)']):'<div class="note">No forecasts scored yet. The first horizon completes one hour after a logged release.</div>';$('calibOut').innerHTML=table(cb,['Horizon','Model said','Actually went up','Events','Chance baseline']);$('forecastLogOut').innerHTML=table(logs,['Forecasted','Event','Release','Call','P(up)','Actual','1h outcome'])}init();
</script></main></body></html>'''.replace('__DATABASE__',json.dumps(payload,separators=(',',':')))
